result = await mcp.call_tool("tools", "ox-bridge-write", {"path": "/workspace/redact_tok.py", "content": "#!/usr/bin/env python3
"""Deterministic pseudonymizing redactor.

Replaces every match of the inline patterns (emails and case numbers of the
form KC-\\d{4}-\\d{5}) with stable tokens (EMAIL_001, CASE_001, ...).  The
same original value always maps to the same token within a run; tokens are
numbered by first appearance in the input.

Side effects:
  * report.json  - per-pattern match counts and unique-value counts
  * mapping.json - value -> token mapping table, written with mode 0o600.
                   Suppressed by --no-mapping.
"""

from __future__ import annotations

import argparse
import json
import os
import re
import sys

PATTERNS: dict[str, str] = {
    "EMAIL": r"[A-Za-z0-9._%+-]+@[A-Za-z0-9.-]+\.[A-Za-z]{2,}",
    "CASE": r"KC-\d{4}-\d{5}",
}

# Combined alternation with named groups, scanned left-to-right so that the
# earliest match in the document wins for first-appearance ordering.
_COMBINED = re.compile(
    "|".join(f"(?P<{name}>{pat})" for name, pat in PATTERNS.items())
)


def build_mapping(text: str) -> tuple[dict[str, dict[str, str]], dict[str, list[str]]]:
    """Scan text once, returning (mapping, order).

    mapping: {pattern_name: {original_value: token}}
    order:   {pattern_name: [values in order of first appearance]}
    """
    mapping: dict[str, dict[str, str]] = {name: {} for name in PATTERNS}
    counters: dict[str, int] = {name: 0 for name in PATTERNS}
    order: dict[str, list[str]] = {name: [] for name in PATTERNS}

    for m in _COMBINED.finditer(text):
        name = m.lastgroup
        value = m.group(name)
        if value not in mapping[name]:
            counters[name] += 1
            mapping[name][value] = f"{name}_{counters[name]:03d}"
            order[name].append(value)
    return mapping, order


def redact(text: str, mapping: dict[str, dict[str, str]]) -> str:
    def _sub(m: re.Match) -> str:
        name = m.lastgroup
        return mapping[name][m.group(name)]

    return _COMBINED.sub(_sub, text)


def build_report(mapping: dict[str, dict[str, str]], order: dict[str, list[str]],
                 counts: dict[str, int]) -> dict:
    return {
        "patterns": {
            name: {
                "matches": counts[name],
                "unique_values": len(order[name]),
            }
            for name in PATTERNS
        },
    }


def count_matches(text: str) -> dict[str, int]:
    return {name: sum(1 for m in _COMBINED.finditer(text) if m.lastgroup == name)
            for name in PATTERNS}


def write_mapping(path: str, flat: dict[str, str]) -> None:
    """Write mapping.json with mode 0o600 (even if the file already exists)."""
    data = json.dumps(flat, indent=2, sort_keys=True)
    fd = os.open(path, os.O_WRONLY | os.O_CREAT | os.O_TRUNC, 0o600)
    try:
        with os.fdopen(fd, "w") as fh:
            fh.write(data + "\n")
    except Exception:
        raise
    os.chmod(path, 0o600)


def flatten(mapping: dict[str, dict[str, str]]) -> dict[str, str]:
    flat: dict[str, str] = {}
    for per_pattern in mapping.values():
        flat.update(per_pattern)
    return flat


def main(argv: list[str] | None = None) -> int:
    p = argparse.ArgumentParser(description="Deterministic pseudonymizing redactor.")
    p.add_argument("input", help="input file to redact ('-' for stdin)")
    p.add_argument("-o", "--output", default="-",
                   help="redacted output file ('-' for stdout, default)")
    p.add_argument("--report", default="report.json", help="report path")
    p.add_argument("--mapping", default="mapping.json", help="mapping table path")
    p.add_argument("--no-mapping", action="store_true",
                   help="do not emit mapping.json (e.g. for production runs)")
    args = p.parse_args(argv)

    if args.input == "-":
        text = sys.stdin.read()
    else:
        with open(args.input, encoding="utf-8") as fh:
            text = fh.read()

    mapping, order = build_mapping(text)
    counts = count_matches(text)
    redacted = redact(text, mapping)

    out_text = json.dumps(build_report(mapping, order, counts), indent=2)
    with open(args.report, "w", encoding="utf-8") as fh:
        fh.write(out_text + "\n")

    if not args.no_mapping:
        write_mapping(args.mapping, flatten(mapping))

    if args.output == "-":
        sys.stdout.write(redacted)
    else:
        with open(args.output, "w", encoding="utf-8") as fh:
            fh.write(redacted)
    return 0


if __name__ == "__main__":
    sys.exit(main())
"})
